   156→      AggregatorFactory[] aggregators
   157→  )
   158→  {
   159→    final Set<String> dimensionExclusions = new HashSet<>();
   160→
   161→    final String timestampColumn = timestampSpec.getTimestampColumn();
   162→    if (!(dimensionsSpec.hasCustomDimensions() && dimensionsSpec.getDimensionNames().contains(timestampColumn))) {
