   195→  private static void hieraricalPutValue(
   196→      String propertyPrefix,
   197→      String originalProperty,
   198→      String property,
   199→      Object value,
   200→      Map<String, Object> targetMap
   201→  )
   202→  {
   203→    int dotIndex = property.indexOf('.');
   204→    // Always put property with name even if it is of form a.b. This will make sure the property is available for classes
   205→    // where JsonProperty names are of the form a.b
   206→    // Note:- this will cause more than required properties to be present in the jsonMap.
   207→    targetMap.put(property, value);
   208→    if (dotIndex < 0) {
   209→      return;
   210→    }
   211→    if (dotIndex == 0) {
   212→      throw new ProvisionException(StringUtils.format("Double dot in property: %s", originalProperty));
   213→    }
   214→    if (dotIndex == property.length() - 1) {
   215→      throw new ProvisionException(StringUtils.format("Dot at the end of property: %s", originalProperty));
   216→    }
   217→    String nestedKey = property.substring(0, dotIndex);
   218→    Object nested = targetMap.computeIfAbsent(nestedKey, k -> new HashMap<String, Object>());
   219→    if (!(nested instanceof Map)) {
   220→      // Clash is possible between properties, which are used to configure different objects: e. g.
   221→      // druid.emitter=parametrized is used to configure Emitter class, and druid.emitter.parametrized.xxx=yyy is used
   222→      // to configure ParametrizedUriEmitterConfig object. So skipping xxx=yyy key-value pair when configuring Emitter
   223→      // doesn't make any difference. That is why we just log this situation, instead of throwing an exception.
   224→      log.info(
   225→          "Skipping %s property: one of it's prefixes is also used as a property key. Prefix: %s",
   226→          originalProperty,
   227→          propertyPrefix
   228→      );
   229→      return;
   230→    }
   231→    Map<String, Object> nestedMap = (Map<String, Object>) nested;
   232→    hieraricalPutValue(propertyPrefix, originalProperty, property.substring(dotIndex + 1), value, nestedMap);
   233→  }
   234→
   235→  @VisibleForTesting
   236→  public static <T> void verifyClazzIsConfigurable(
   237→      ObjectMapper mapper,
   238→      Class<T> clazz,
   239→      @Nullable Class<? extends T> defaultClass
   240→  )
   241→  {
   242→    if (defaultClass != null) {
   243→      try {
   244→        defaultClass.getConstructor();
   245→      }
   246→      catch (NoSuchMethodException e) {
   247→        throw new ProvisionException(
   248→            StringUtils.format(
   249→                "JsonConfigurator requires default classes to have zero-arg constructors. %s doesn't",
   250→                defaultClass
   251→            )
   252→        );
   253→      }
   254→    }
   255→
   256→    final List<BeanPropertyDefinition> beanDefs = mapper.getSerializationConfig()
   257→                                                        .introspect(mapper.constructType(clazz))
   258→                                                        .findProperties();
   259→    for (BeanPropertyDefinition beanDef : beanDefs) {
   260→      final AnnotatedField field = beanDef.getField();
   261→      if (field == null || !field.hasAnnotation(JsonProperty.class)) {
   262→        throw new ProvisionException(
   263→            StringUtils.format(
   264→                "JsonConfigurator requires Jackson-annotated Config objects to have field annotations. %s doesn't",
   265→                clazz
   266→            )
   267→        );
   268→      }
   269→    }
   270→  }
   271→}
